<script setup lang="ts">import {ref} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const account=ref('');const code=ref('');const password=ref('');const confirm=ref('');const accepted=ref(false);const loading=ref(false);const countdown=ref(0);function deviceInfo(){let sys:any={};try{sys=uni.getSystemInfoSync()||{}}catch{}const platform=String(sys.platform||'').toLowerCase();let deviceId='';try{deviceId=uni.getStorageSync('cf_device_id')||''}catch{};if(!deviceId){deviceId='dev-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10);try{uni.setStorageSync('cf_device_id',deviceId)}catch{}}let appVersion=sys.appVersion||'0.1.0';try{const rt=(globalThis as any).plus?.runtime?.version;if(rt)appVersion=rt}catch{}return{deviceId,deviceType:platform==='ios'?1:2,systemVersion:sys.system||sys.osVersion||'',appVersion}}async function sendCode(){if(countdown.value)return;if(!account.value.trim())return uni.showToast({title:t('请输入邮箱'),icon:'none'});try{await api.sendLoginCode(account.value.trim(),1);countdown.value=60;const timer=setInterval(()=>{countdown.value-=1;if(!countdown.value)clearInterval(timer)},1000)}catch(error:any){uni.showToast({title:error?.message||t('验证码发送失败'),icon:'none'})}}async function submit(){if(!account.value||!code.value||!password.value)return uni.showToast({title:t('请完整填写注册信息'),icon:'none'});if(password.value!==confirm.value)return uni.showToast({title:t('两次密码不一致'),icon:'none'});if(!accepted.value)return uni.showToast({title:t('请先同意协议'),icon:'none'});loading.value=true;try{await api.register({email:account.value,password:password.value,code:code.value,...deviceInfo()});uni.showToast({title:t('注册成功，请登录'),icon:'none'});setTimeout(()=>uni.navigateBack(),500)}catch(error:any){uni.showToast({title:error?.message||t('注册失败'),icon:'none'})}finally{loading.value=false}}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('创建账户')}}</text></view><view class="inner-main"><view class="inner-heading">{{t('创建账户')}}</view><view class="inner-subtitle">{{t('加入 Crypto Flash 专业交易终端')}}</view><view class="inner-card register-card"><view class="form-field"><text class="form-label">{{t('邮箱或手机号')}}</text><input v-model="account" class="form-input" :placeholder="t('输入邮箱或手机号')"/></view><view class="form-field"><text class="form-label">{{t('验证码')}}</text><view class="code-row"><input v-model="code" class="form-input" :placeholder="t('输入验证码')"/><button class="code-button" :disabled="!!countdown" @click="sendCode">{{t('发送验证码')}}</button></view></view><view class="form-field"><text class="form-label">{{t('设置密码')}}</text><input v-model="password" class="form-input" password :placeholder="t('设置密码')"/></view><view class="form-field"><text class="form-label">{{t('确认密码')}}</text><input v-model="confirm" class="form-input" password :placeholder="t('再次输入密码')"/></view><view class="agreement"><checkbox :checked="accepted" @click="accepted=!accepted"/>{{t('同意服务协议与隐私条款')}}</view><button class="action-button" @click="submit">{{t('注册并登录')}}</button></view></view></view></template>
<style scoped>.register-card{margin-top:24rpx}.agreement{display:flex;align-items:center;gap:6rpx;margin:4rpx 0 20rpx;color:var(--cf-muted);font-size:18rpx}.agreement checkbox{transform:scale(.72);margin:0}.code-row{display:flex;align-items:center;gap:10rpx}.code-row .form-input{flex:1;min-width:0}.code-button{flex:0 0 170rpx;height:72rpx;padding:0;border:1rpx solid #BFDBFE;border-radius:12rpx;background:#EFF6FF;color:var(--cf-brand);font-size:19rpx}.code-button[disabled]{color:var(--cf-soft);background:#F8FAFC;border-color:var(--cf-line)}</style>
